operators.code:
// Arithmetic
const sum = 10 + 5;
const mod = 10 % 3;
const pow = 2 ** 3;

// Comparison
const eq = (5 === "5");  // false (Strict equality)
const looseEq = (5 == "5"); // true (Type coercion)

// Logical & Nullish Coalescing
const isTrue = true && false || true;
const defaultVal = null ?? "default";

conditionals.code:
const age = 20;

if (age < 13) {
  console.log("Child");
} else if (age < 20) {
  console.log("Teen");
} else {
  console.log("Adult");
}

// Ternary
const status = age >= 18 ? "Adult" : "Minor";

// Switch
switch(status) {
  case "Adult": break;
  default: break;
}

for_loop.code:
const items = ['a', 'b', 'c'];

// Traditional C-style loop
for (let i = 0; i < items.length; i++) {
  console.log(items[i]);
}

// for...of (Iterable objects like arrays)
for (const item of items) {
  console.log(item);
}

// forEach (Array method)
items.forEach((item, index) => console.log(item));

while_loop.code:
let count = 0;

// standard while loop
while (count < 5) {
  console.log(count);
  count++;
}

// do...while (executes at least once)
let x = 10;
do {
  console.log(x);
  x--;
} while (x > 10);

functions.code:
// Function declaration (Hoisted)
function add(a, b = 0) {
  return a + b;
}

// Arrow function (Lexical 'this')
const multiply = (a, b) => {
  return a * b;
};

// Concise arrow function
const square = x => x * x;

// Rest parameters
const sumAll = (...args) => args.reduce((a, b) => a + b, 0);

arrays.code:
const nums = [1, 2, 3];

// Mutation
nums.push(4);

// Functional (non-mutating) methods
const doubled = nums.map(n => n * 2);
const evens = nums.filter(n => n % 2 === 0);

// Spread operator
const combined = [...nums, 5, 6];

maps.code:
// Object as dictionary (String/Symbol keys only)
const obj = { name: "Alice", age: 30 };
obj.role = "admin";

// Map (Any type of key, preserves insertion order)
const map = new Map();
map.set("name", "Bob");
map.set(1, "number key");

// Iteration
for (const [key, value] of map.entries()) {
  console.log(`${key}: ${value}`);
}

